#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);
unordered_set<long long>s;
for(int i=0;i<n;++i){long long x;scanf("%lld",&x);s.insert(x);}
set<long long>res;
for(int i=0;i<m;++i){long long x;scanf("%lld",&x);if(s.count(x))res.insert(x);}
bool first=true;
for(long long x:res){if(!first)printf(" ");printf("%lld",x);first=false;}
printf("\n");return 0;}

